EIP-1153 allows attackers to set transient state even in low-gas contexts:

❌ Problem:
1. Traditional guard blocks classic reentrancy
2. But attacker can use TSTORE (100 gas) in receive() fallback
3. Can coordinate multi-step attacks or signal to other contracts

Fix 1: Use checks-effects-interactions pattern ALWAYS
function withdraw() public nonReentrant {
uint256 amount = balances[msg.sender];

// ✅ Update state BEFORE external call
balances[msg.sender] = 0;

payable(msg.sender).transfer(amount);
}

Fix 2: Add read-only reentrancy protection for view functions
uint256 transient private locked;

modifier nonReentrant() {
require(locked == 0, "Reentrant");
locked = 1;
_;
locked = 0;
}

// ✅ Also protect view functions
function getBalance(address user) public view returns (uint256) {
require(locked == 0, "No read during state change");
return balances[user];
}

Fix 3: Use OpenZeppelin ReentrancyGuard v5.0+
// Uses transient storage automatically in Solidity 0.8.24+
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract Secure is ReentrancyGuard {
function withdraw() public nonReentrant {
// Protected against both classic and transient reentrancy
}
}

